from datetime import datetime
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
from fractions import Fraction

CENT = Decimal("0.01")
FOUR = Decimal("0.0001")


def _quantize_frac(value: Fraction, places: int) -> Decimal:
    factor = 10 ** places
    scaled = value * factor
    num = scaled.numerator
    den = scaled.denominator
    if num >= 0:
        rounded = (2 * num + den) // (2 * den)
    else:
        rounded = -((-2 * num + den) // (2 * den))
    return Decimal(rounded).scaleb(-places)


def _q2(value):
    return _quantize_frac(Fraction(value), 2)


def _q4(value):
    return _quantize_frac(Fraction(value), 4)


def _parse_decimal(value, max_places, name):
    if not isinstance(value, str):
        raise ValueError(f"{name} must be a string")
    try:
        amount = Decimal(value)
    except (InvalidOperation, ValueError):
        raise ValueError(f"invalid {name}: {value!r}") from None
    if not amount.is_finite():
        raise ValueError(f"{name} must be finite")
    if amount.as_tuple().exponent < -max_places:
        raise ValueError(f"{name} has too many decimal places")
    return amount


def _parse_date(value):
    if not isinstance(value, str):
        raise ValueError("date must be a string")
    try:
        parsed = datetime.strptime(value, "%Y-%m-%d")
    except ValueError:
        raise ValueError(f"invalid date: {value!r}") from None
    if parsed.strftime("%Y-%m-%d") != value:
        raise ValueError(f"invalid date: {value!r}")
    return value


def fifo_report(trades: list[dict]) -> dict:
    if not isinstance(trades, list):
        raise ValueError("trades must be a list")
    lots = []  # each [remaining_qty:int, remaining_total_cost:Fraction]
    sales = []
    total_realized_frac = Fraction(0)

    for trade in trades:
        if not isinstance(trade, dict):
            raise ValueError("each trade must be a dict")
        for key in ("date", "side", "quantity", "price"):
            if key not in trade:
                raise ValueError(f"trade missing key: {key}")
        date = _parse_date(trade["date"])
        side = trade["side"]
        if side not in ("BUY", "SELL"):
            raise ValueError("side must be BUY or SELL")
        quantity = trade["quantity"]
        if isinstance(quantity, bool) or not isinstance(quantity, int):
            raise ValueError("quantity must be an integer")
        if quantity <= 0:
            raise ValueError("quantity must be > 0")
        price = _parse_decimal(trade["price"], 4, "price")
        if price <= 0:
            raise ValueError("price must be > 0")
        fee = _parse_decimal(trade.get("fee", "0.00"), 2, "fee")
        if fee < 0:
            raise ValueError("fee must be >= 0")
        price_frac = Fraction(price)
        fee_frac = Fraction(fee)

        if side == "BUY":
            lots.append([quantity, quantity * price_frac + fee_frac])
        else:
            inventory = sum(lot[0] for lot in lots)
            if quantity > inventory:
                raise ValueError("insufficient inventory")
            proceeds_exact = quantity * price_frac - fee_frac
            cost_exact = Fraction(0)
            to_sell = quantity
            while to_sell > 0:
                lot_qty, lot_cost = lots[0]
                taken = min(lot_qty, to_sell)
                consumed = lot_cost * taken / lot_qty
                cost_exact += consumed
                if taken == lot_qty:
                    lots.pop(0)
                else:
                    lots[0] = [lot_qty - taken, lot_cost - consumed]
                to_sell -= taken
            realized_q = _quantize_frac(proceeds_exact - cost_exact, 2)
            sales.append(
                {
                    "date": date,
                    "quantity": quantity,
                    "proceeds": _quantize_frac(proceeds_exact, 2),
                    "cost": _quantize_frac(cost_exact, 2),
                    "realized": realized_q,
                }
            )
            total_realized_frac += Fraction(realized_q)

    remaining = []
    inventory_quantity = 0
    for lot_qty, lot_cost in lots:
        if lot_qty > 0:
            remaining.append(
                {
                    "quantity": lot_qty,
                    "unit_cost": _quantize_frac(lot_cost / lot_qty, 4),
                    "total_cost": _quantize_frac(lot_cost, 2),
                }
            )
            inventory_quantity += lot_qty
    return {
        "sales": sales,
        "total_realized": _quantize_frac(total_realized_frac, 2),
        "remaining": remaining,
        "inventory_quantity": inventory_quantity,
    }
